<?php

namespace Tests\Support;

/** Real synthetic black H.264/yuv420p MP4s, generated with Debian FFmpeg 5.1.9.
 * ffmpeg -f lavfi -i color=c=black:s=320xHEIGHT:d=0.1 -threads 1 -c:v libx264 -pix_fmt yuv420p output.mp4
 * Runtime deliberately ships ffprobe only. These bytes still pass through the
 * real inspector; neither encoder availability nor an external provider is needed.
 */
final class SyntheticLineVideo
{
    public static function bytes(int $height): string
    {
        return base64_decode(match ($height) {
            // SHA-256 e5816e62b038977951da81e2cdd2de1d1143d8e64aa70b09243f8fbd8946e2dd
            180 => '',
            // SHA-256 a93738dcefa2ef47b4b4cbfc801fc4284d2b895a0865e478cd292e66c68266b9
            320 => '',
            default => throw new \InvalidArgumentException('Unsupported synthetic video dimensions.'),
        }, true);
    }
}
